import { and, desc, eq, lt, or } from 'drizzle-orm';
import { z } from 'zod';
import { db } from '../../db/client.js';
import { payouts } from '../../db/schema.js';
import { decodeCursor, encodeCursor } from '../../lib/cursor.js';

export const ListPayoutsQuery = z.object({
  cursor: z.string().optional(),
  limit: z.coerce.number().int().min(1).max(100).default(25),
});

export async function listPayouts(orgId: string, query: z.infer<typeof ListPayoutsQuery>) {
  const after = query.cursor ? decodeCursor(query.cursor) : undefined;
  const rows = await db
    .select()
    .from(payouts)
    .where(
      and(
        eq(payouts.orgId, orgId),
        after
          ? or(lt(payouts.createdAt, after.createdAt), and(eq(payouts.createdAt, after.createdAt), lt(payouts.id, after.id)))
          : undefined,
      ),
    )
    .orderBy(desc(payouts.createdAt), desc(payouts.id))
    .limit(query.limit + 1);

  const hasMore = rows.length > query.limit;
  const page = hasMore ? rows.slice(0, query.limit) : rows;
  const last = page.at(-1);
  return {
    data: page.map((p) => ({ id: p.id, amountCents: p.amountCents, currency: p.currency, status: p.status, arrivalDate: p.arrivalDate })),
    nextCursor: hasMore && last ? encodeCursor({ createdAt: last.createdAt, id: last.id }) : null,
  };
}

