    }
    const orgId = req.auth.orgId;
    const [row] = await db
      .update(customers)
      .set({ deletedAt: new Date() })
      .where(and(eq(customers.id, parsed.data.id), eq(customers.orgId, orgId), isNull(customers.deletedAt)))
      .returning({ id: customers.id });
    if (!row) {
      return problem(reply, 404, 'Customer not found');
    }
    return reply.code(204).send();
  });
};

