          <AlertDialogAction
            disabled={pending}
            onClick={(e) => {
              e.preventDefault();
              startTransition(async () => {
                const res = await deleteCustomer(id);
                if (res?.error) setError(res.error);
              });
            }}
          >
            {pending ? 'Deleting...' : 'Delete'}
