export async function deleteCustomer(id: string): Promise<{ error: string } | undefined> {
  const res = await apiFetch(`/v1/customers/${id}`, { method: 'DELETE' });
  if (!res.ok) {
    const body = (await res.json().catch(() => null)) as { title?: string } | null;
    return { error: body?.title ?? 'Could not delete customer' };
  }
  revalidatePath('/customers');
  redirect('/customers');
}

