import { Queue, Worker } from 'bullmq';
import { addDays, endOfDay, startOfDay } from 'date-fns';
import { connection } from '../redis.js';
import { logger } from '../logger.js';
import { findInvoicesDueBetween, listActiveOrgIds } from '../db/invoices.js';
import { emailsQueue } from './emails.js';

const ONE_SECOND_MS = 1_000;

export const invoiceRemindersQueue = new Queue('invoice-reminders', {
  connection,
  defaultJobOptions: {
    attempts: 3,
    backoff: { type: 'exponential', delay: ONE_SECOND_MS },
  },
});

export async function scheduleInvoiceReminders() {
  await invoiceRemindersQueue.upsertJobScheduler('daily-invoice-reminders', { pattern: '0 13 * * *' }, { name: 'fan-out' });
}

export const invoiceRemindersWorker = new Worker(
  'invoice-reminders',
  async (job) => {
    if (job.name === 'fan-out') {
      const orgIds = await listActiveOrgIds();
      await invoiceRemindersQueue.addBulk(orgIds.map((orgId) => ({ name: 'org', data: { orgId } })));
      return { orgs: orgIds.length };
    }
    const { orgId } = job.data as { orgId: string };
    const target = addDays(new Date(), 3);
    const due = await findInvoicesDueBetween(orgId, startOfDay(target), endOfDay(target));
    await emailsQueue.addBulk(
      due.map((inv) => ({
        name: 'invoice-reminder',
        data: { orgId, invoiceId: inv.id },
        opts: { jobId: `invoice-reminder:${inv.id}:${target.toISOString().slice(0, 10)}` },
      })),
    );
    logger.info({ orgId, count: due.length }, 'invoice reminders enqueued');
    return { reminders: due.length };
  },
  { connection, concurrency: 5 },
);

